# Aircraft Maintenance Platform

Tagup take-home exercise. Setup and run instructions coming soon.
[project]
name = "maintenance"
version = "0.1.0"
description = "Aircraft maintenance write-up tracker"
requires-python = ">=3.12"
dependencies = [
    "fastapi",
    "jinja2>=3.1.6",
    "python-multipart",
    "sqlalchemy",
    "uvicorn",
]

[dependency-groups]
dev = [
    "httpx",
    "pytest",
]

[tool.pytest.ini_options]
testpaths = ["tests"]
pythonpath = ["."]
import sys
from pathlib import Path

import uvicorn
from sqlalchemy.orm import Session

from app.db import create_db
from app.main import create_app, local_now
from app.seed import seed_if_empty

DB_PATH = Path("maintenance.db")

if "--reset" in sys.argv:
    DB_PATH.unlink(missing_ok=True)

engine = create_db(f"sqlite:///{DB_PATH}")
with Session(engine) as session:
    seed_if_empty(session, local_now())

uvicorn.run(create_app(engine), host="127.0.0.1", port=8000)
from sqlalchemy import create_engine, event

from app.models import Base


def create_db(url):
    engine = create_engine(url)

    @event.listens_for(engine, "connect")
    def enable_foreign_keys(dbapi_connection, _):
        # SQLite ignores foreign keys unless each connection opts in.
        dbapi_connection.execute("PRAGMA foreign_keys = ON")

    Base.metadata.create_all(engine)
    return engine
from datetime import date, datetime
from enum import StrEnum

from sqlalchemy import CheckConstraint, Enum, ForeignKey, Index
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship

from app.rules import Severity, Status


class EventKind(StrEnum):
    scheduled = "scheduled"
    rescheduled = "rescheduled"
    unscheduled = "unscheduled"
    started = "started"
    resolved = "resolved"
    canceled = "canceled"
    severity_changed = "severity_changed"
    description_edited = "description_edited"


def _enum(cls):
    return Enum(cls, native_enum=False, create_constraint=True, length=20)


def _not_blank(column):
    return CheckConstraint(f"length(trim({column})) > 0", name=f"{column}_not_blank")


class Base(DeclarativeBase):
    pass


class Aircraft(Base):
    __tablename__ = "aircraft"
    __table_args__ = (_not_blank("tail_number"),)

    id: Mapped[int] = mapped_column(primary_key=True)
    tail_number: Mapped[str] = mapped_column(unique=True)

    writeups: Mapped[list["Writeup"]] = relationship(back_populates="aircraft", order_by="Writeup.id")


class Writeup(Base):
    __tablename__ = "writeup"
    __table_args__ = (
        _not_blank("description"),
        _not_blank("reported_by"),
        CheckConstraint(
            "(status = 'unscheduled' AND scheduled_date IS NULL)"
            " OR (status IN ('scheduled', 'in_progress', 'resolved') AND scheduled_date IS NOT NULL)"
            " OR status = 'canceled'",
            name="scheduled_date_matches_status",
        ),
        Index("ix_writeup_aircraft_status", "aircraft_id", "status"),
        Index("ix_writeup_status", "status"),
    )

    id: Mapped[int] = mapped_column(primary_key=True)
    aircraft_id: Mapped[int] = mapped_column(ForeignKey("aircraft.id"))
    description: Mapped[str]
    severity: Mapped[Severity] = mapped_column(_enum(Severity))
    status: Mapped[Status] = mapped_column(_enum(Status))
    scheduled_date: Mapped[date | None]
    reported_by: Mapped[str]
    # Naive UTC: SQLite has no time zone type.
    reported_at: Mapped[datetime]
    version: Mapped[int] = mapped_column()

    # Each update checks the version it read, so a change made in between fails instead of being overwritten.
    __mapper_args__ = {"version_id_col": version}

    aircraft: Mapped[Aircraft] = relationship(back_populates="writeups")
    events: Mapped[list["WriteupEvent"]] = relationship(order_by="WriteupEvent.id")


class WriteupEvent(Base):
    __tablename__ = "writeup_event"
    __table_args__ = (
        _not_blank("actor"),
        CheckConstraint(
            "kind NOT IN ('resolved', 'canceled', 'severity_changed')"
            " OR (note IS NOT NULL AND length(trim(note)) > 0)",
            name="note_required",
        ),
    )

    id: Mapped[int] = mapped_column(primary_key=True)
    writeup_id: Mapped[int] = mapped_column(ForeignKey("writeup.id"), index=True)
    # Naive UTC: SQLite has no time zone type.
    at: Mapped[datetime]
    actor: Mapped[str]
    kind: Mapped[EventKind] = mapped_column(_enum(EventKind))
    from_value: Mapped[str | None]
    to_value: Mapped[str | None]
    note: Mapped[str | None]
from enum import StrEnum


class Severity(StrEnum):
    high = "high"
    medium = "medium"
    low = "low"


class Status(StrEnum):
    unscheduled = "unscheduled"
    scheduled = "scheduled"
    in_progress = "in_progress"
    resolved = "resolved"
    canceled = "canceled"


OPEN_STATUSES = {Status.unscheduled, Status.scheduled, Status.in_progress}


def grounding(writeups):
    return [w for w in writeups if w.severity == Severity.high and w.status in OPEN_STATUSES]


def is_cleared(writeups):
    return not grounding(writeups)


class RuleViolation(Exception):
    pass


class WrongStatus(RuleViolation):
    pass


def is_overdue(writeup, today):
    return writeup.status in {Status.scheduled, Status.in_progress} and writeup.scheduled_date < today


def schedule(status, current_date, new_date, today):
    _require_open(status)
    if new_date < today:
        raise RuleViolation("The scheduled date can't be in the past.")
    if new_date == current_date:
        raise RuleViolation("The write-up is already scheduled for that date.")
    if status == Status.unscheduled:
        return Status.scheduled
    return status


def unschedule(status):
    _require_status(status, {Status.scheduled}, "Only a scheduled write-up can be unscheduled.")
    return Status.unscheduled


def start(status):
    _require_status(status, {Status.scheduled}, "Only a scheduled write-up can be started.")
    return Status.in_progress


def resolve(status):
    _require_status(status, {Status.in_progress}, "Only an in-progress write-up can be resolved.")
    return Status.resolved


def cancel(status):
    _require_open(status)
    return Status.canceled


def change_severity(status, current, new):
    _require_open(status)
    if new == current:
        raise RuleViolation(f"Severity is already {current}.")


def edit_description(status, current, new):
    _require_open(status)
    if new == current:
        raise RuleViolation("The description hasn't changed.")


def require_text(value, field):
    value = value.strip()
    if not value:
        raise RuleViolation(f"{field} is required.")
    return value


def _require_open(status):
    _require_status(status, OPEN_STATUSES, f"A {status} write-up can't be changed.")


def _require_status(status, allowed, message):
    if status not in allowed:
        raise WrongStatus(message)
from dataclasses import dataclass
from datetime import UTC, date, datetime

from sqlalchemy import select

from app import rules
from app.models import Aircraft, EventKind, Writeup, WriteupEvent
from app.rules import OPEN_STATUSES, Severity, Status, require_text


@dataclass
class AircraftStatus:
    aircraft: Aircraft
    open_writeups: list[Writeup]

    @property
    def cleared(self):
        return rules.is_cleared(self.open_writeups)

    @property
    def grounding(self):
        return rules.grounding(self.open_writeups)

    @property
    def needs_scheduling(self):
        return any(w.status == Status.unscheduled for w in self.open_writeups)

    @property
    def next_date(self):
        return min((w.scheduled_date for w in self.open_writeups if w.scheduled_date), default=None)

    def is_overdue(self, today):
        return any(rules.is_overdue(w, today) for w in self.open_writeups)


def fleet_status(session):
    aircraft = session.scalars(select(Aircraft).order_by(Aircraft.tail_number)).all()
    open_writeups = session.scalars(select(Writeup).where(Writeup.status.in_(OPEN_STATUSES))).all()
    by_aircraft = {plane.id: [] for plane in aircraft}
    for writeup in open_writeups:
        by_aircraft[writeup.aircraft_id].append(writeup)
    return [AircraftStatus(plane, by_severity(by_aircraft[plane.id])) for plane in aircraft]


@dataclass
class Board:
    grounded: list[AircraftStatus]
    cleared: list[AircraftStatus]
    fleet_size: int
    grounded_count: int


def board(session, today, query=""):
    fleet = fleet_status(session)
    query = query.strip().lower()
    shown = [s for s in fleet if query in s.aircraft.tail_number.lower()]
    shown.sort(key=lambda s: (
        not s.is_overdue(today), not s.needs_scheduling, s.next_date or date.max, s.aircraft.tail_number,
    ))
    return Board(
        grounded=[s for s in shown if not s.cleared],
        cleared=[s for s in shown if s.cleared],
        fleet_size=len(fleet),
        grounded_count=sum(not s.cleared for s in fleet),
    )


@dataclass
class TimelineEntry:
    at: datetime
    actor: str
    writeup: Writeup
    event: WriteupEvent | None  # None is the filing itself, which lives on the write-up row (A9).


def timeline(aircraft):
    entries = []
    for writeup in aircraft.writeups:
        entries.append(TimelineEntry(writeup.reported_at, writeup.reported_by, writeup, None))
        entries += [TimelineEntry(event.at, event.actor, writeup, event) for event in writeup.events]
    # Reversing a stable sort, rather than sorting descending, puts same-instant entries newest first too.
    return sorted(entries, key=lambda entry: entry.at)[::-1]


def filed_severity(writeup):
    # Filing isn't an audit-log row (A9), so the severity at filing is whatever the first change replaced.
    changes = [event for event in writeup.events if event.kind == EventKind.severity_changed]
    return changes[0].from_value if changes else writeup.severity


def open_writeups(aircraft):
    return by_severity(w for w in aircraft.writeups if w.status in OPEN_STATUSES)


def by_severity(writeups):
    severity_rank = list(Severity).index
    return sorted(writeups, key=lambda w: (severity_rank(w.severity), w.id))


def file_writeup(session, aircraft_id, reported_by, description, severity, now, scheduled_date=None):
    writeup = Writeup(
        aircraft_id=aircraft_id,
        reported_by=require_text(reported_by, "Name"),
        description=require_text(description, "Description"),
        severity=severity,
        status=Status.unscheduled,
        reported_at=_utc(now),
    )
    session.add(writeup)
    session.flush()
    if scheduled_date is not None:
        schedule(session, writeup, reported_by, scheduled_date, now)
    return writeup


def schedule(session, writeup, actor, new_date, now):
    actor = require_text(actor, "Name")
    old_date = writeup.scheduled_date
    kind = EventKind.scheduled if old_date is None else EventKind.rescheduled
    writeup.status = rules.schedule(writeup.status, old_date, new_date, today(now))
    writeup.scheduled_date = new_date
    _log(session, writeup, kind, actor, now, from_value=None if old_date is None else old_date.isoformat(), to_value=new_date.isoformat())


def unschedule(session, writeup, actor, now):
    actor = require_text(actor, "Name")
    writeup.status = rules.unschedule(writeup.status)
    old_date = writeup.scheduled_date
    writeup.scheduled_date = None
    _log(session, writeup, EventKind.unscheduled, actor, now, from_value=old_date.isoformat())


def start(session, writeup, actor, now):
    actor = require_text(actor, "Name")
    writeup.status = rules.start(writeup.status)
    _log(session, writeup, EventKind.started, actor, now)


def resolve(session, writeup, actor, note, now):
    actor = require_text(actor, "Name")
    note = require_text(note, "What was done")
    writeup.status = rules.resolve(writeup.status)
    _log(session, writeup, EventKind.resolved, actor, now, note=note)


def cancel(session, writeup, actor, note, now):
    actor = require_text(actor, "Name")
    note = require_text(note, "Reason")
    writeup.status = rules.cancel(writeup.status)
    _log(session, writeup, EventKind.canceled, actor, now, note=note)


def change_severity(session, writeup, actor, severity, note, now):
    actor = require_text(actor, "Name")
    note = require_text(note, "Reason")
    old = writeup.severity
    rules.change_severity(writeup.status, old, severity)
    writeup.severity = severity
    _log(session, writeup, EventKind.severity_changed, actor, now, from_value=old, to_value=severity, note=note)


def edit_description(session, writeup, actor, description, now):
    actor = require_text(actor, "Name")
    description = require_text(description, "Description")
    old = writeup.description
    rules.edit_description(writeup.status, old, description)
    writeup.description = description
    _log(session, writeup, EventKind.description_edited, actor, now, from_value=old, to_value=description)


def today(now):
    return now.date()


def _log(session, writeup, kind, actor, now, from_value=None, to_value=None, note=None):
    session.add(
        WriteupEvent(
            writeup_id=writeup.id,
            at=_utc(now),
            actor=actor,
            kind=kind,
            from_value=from_value,
            to_value=to_value,
            note=note,
        )
    )


def _utc(now):
    return now.astimezone(UTC).replace(tzinfo=None)

from dataclasses import dataclass
from datetime import UTC, date, datetime
from pathlib import Path
from typing import Annotated
from urllib.parse import urlencode

from fastapi import Depends, FastAPI, Form, HTTPException, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import PlainTextResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles
from fastapi.templating import Jinja2Templates
from sqlalchemy import select
from sqlalchemy.orm import Session
from sqlalchemy.orm.exc import StaleDataError

from app import service
from app.models import Aircraft, Writeup
from app.rules import RuleViolation, Severity, WrongStatus, is_overdue

HERE = Path(__file__).parent

FIELD_LABELS = {
    "severity": "Severity",
    "scheduled_date": "Date",
    "actor": "Name",
    "reported_by": "Name",
    "description": "Description",
    "note": "Note",
}


def local_now():
    # Local time with its zone attached: "today" is the server's local date (A8).
    return datetime.now().astimezone()


def day(value):
    if isinstance(value, str):
        value = date.fromisoformat(value)
    return f"{value.day} {value:%b %Y}"


def local_time(at):
    # Stored as naive UTC (models.py); shown in the server's zone, the same one "today" uses,
    # at the offset that zone had on that date.
    at = at.replace(tzinfo=UTC).astimezone()
    return f"{at.day} {at:%b %H:%M}"


templates = Jinja2Templates(directory=HERE / "templates")
templates.env.filters["day"] = day
templates.env.filters["local_time"] = local_time
templates.env.globals["Severity"] = Severity
templates.env.globals["is_overdue"] = is_overdue
templates.env.globals["filed_severity"] = service.filed_severity


def get_session(request: Request):
    with Session(request.app.state.engine) as session:
        yield session


def get_now(request: Request):
    return request.app.state.clock()


DbSession = Annotated[Session, Depends(get_session)]
Now = Annotated[datetime, Depends(get_now)]
Text = Annotated[str, Form()]


def load_writeup(writeup_id: int, session: DbSession):
    writeup = session.get(Writeup, writeup_id)
    if writeup is None:
        raise HTTPException(404, "Write-up not found")
    return writeup


LoadedWriteup = Annotated[Writeup, Depends(load_writeup)]


@dataclass
class Failure:
    form_id: str
    message: str
    values: dict


def board_url(query="", hidden=(), tail=""):
    params = [("q", query)] if query else []
    params += [("hide", group) for group in sorted(hidden)]
    if tail:
        params.append(("aircraft", tail))
    return "/?" + urlencode(params) if params else "/"


def board_linker(query, hidden, tail):
    """Builds links from the current board, changing only what the caller names."""
    def link(query=query, tail=tail, toggle=None):
        return board_url(query, hidden ^ {toggle} if toggle else hidden, tail)
    return link


def board_state(request):
    """The search and hidden groups ride along on every link and form so no click loses them."""
    return request.query_params.get("q", ""), set(request.query_params.getlist("hide"))


def done(request, session, writeup):
    query, hidden = board_state(request)
    location = f"{board_url(query, hidden, writeup.aircraft.tail_number)}#writeup-{writeup.id}"
    # Commit here rather than when get_session exits: FastAPI has already sent the response
    # by then, so a failed commit would go unreported.
    session.commit()
    return RedirectResponse(location, status_code=303)


def render_board(request, session, now, tail="", failure=None):
    query, hidden = board_state(request)
    aircraft = None
    if tail:
        aircraft = session.scalar(select(Aircraft).where(Aircraft.tail_number == tail))
        if aircraft is None:
            raise HTTPException(404, "Aircraft not found")
    today = service.today(now)
    context = {
        "board": service.board(session, today, query),
        "query": query,
        "hidden": hidden,
        "link": board_linker(query, hidden, tail),
        "form_query": board_url(query, hidden).removeprefix("/"),
        "aircraft": aircraft,
        "now": now,
        "today": today,
        "failure": failure,
    }
    if aircraft:
        context["status"] = service.AircraftStatus(aircraft, service.open_writeups(aircraft))
        context["timeline"] = service.timeline(aircraft)
    return templates.TemplateResponse(request, "board.html", context, status_code=400 if failure else 200)


async def render_failure(request, message, stale=False):
    """Re-renders the aircraft the failed form belonged to, with the message and what was typed."""
    params = request.path_params
    with Session(request.app.state.engine) as session:
        if "writeup_id" in params:
            writeup = session.get(Writeup, int(params["writeup_id"]))
            tail = writeup.aircraft.tail_number
            if stale:
                # The form that was submitted isn't on the card any more, so the panel carries the message.
                form_id = "panel"
                message = f"Write-up #{writeup.id} has changed since this page loaded. {message}"
            else:
                form_id = f"{writeup.id}-{request.url.path.rsplit('/', 1)[1]}"
        else:
            aircraft = session.get(Aircraft, int(params["aircraft_id"]))
            if aircraft is None:
                return PlainTextResponse("Aircraft not found", status_code=404)
            tail = aircraft.tail_number
            form_id = "file"
        failure = Failure(form_id, message, dict(await request.form()))
        return render_board(request, session, get_now(request), tail=tail, failure=failure)


def create_app(engine, clock=local_now):
    app = FastAPI()
    app.state.engine = engine
    app.state.clock = clock
    app.mount("/static", StaticFiles(directory=HERE / "static"), name="static")

    @app.exception_handler(RuleViolation)
    async def rule_violation(request, exc):
        return await render_failure(request, str(exc), stale=isinstance(exc, WrongStatus))

    @app.exception_handler(StaleDataError)
    async def changed_meanwhile(request, exc):
        return await render_failure(request, "Nothing was saved.", stale=True)

    @app.exception_handler(RequestValidationError)
    async def invalid_form(request, exc):
        if any(error["loc"][0] == "path" for error in exc.errors()):
            return PlainTextResponse("Not found", status_code=404)
        message = " ".join(
            f"{FIELD_LABELS[error['loc'][-1]]} is {'required' if error['type'] == 'missing' else 'invalid'}."
            for error in exc.errors()
        )
        return await render_failure(request, message)

    @app.get("/")
    def fleet(request: Request, session: DbSession, now: Now, aircraft: str = ""):
        return render_board(request, session, now, aircraft)

    # Text fields default to "" because FastAPI treats an empty form field as missing
    # and Annotated[..., Form()] can't carry a default; require_text in the service then
    # rejects blank and missing alike with a readable message.

    @app.post("/aircraft/{aircraft_id}/writeups")
    def file_writeup(
        request: Request, aircraft_id: int, session: DbSession, now: Now, severity: Annotated[Severity, Form()],
        reported_by: Text = "", description: Text = "", scheduled_date: Annotated[date | None, Form()] = None,
    ):
        if session.get(Aircraft, aircraft_id) is None:
            raise HTTPException(404, "Aircraft not found")
        writeup = service.file_writeup(session, aircraft_id, reported_by, description, severity, now, scheduled_date)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/schedule")
    def schedule(
        request: Request, writeup: LoadedWriteup, session: DbSession, now: Now,
        scheduled_date: Annotated[date, Form()], actor: Text = "",
    ):
        service.schedule(session, writeup, actor, scheduled_date, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/unschedule")
