def board_url(query="", hidden=(), tail=""):
    params = [("q", query)] if query else []
    params += [("hide", group) for group in sorted(hidden)]
    if tail:
        params.append(("aircraft", tail))
    return "/?" + urlencode(params) if params else "/"


def board_linker(query, hidden, tail):
    """Builds links from the current board, changing only what the caller names."""
    def link(query=query, tail=tail, toggle=None):
        return board_url(query, hidden ^ {toggle} if toggle else hidden, tail)
    return link


def board_state(request):
    """The search and hidden groups ride along on every link and form so no click loses them."""
    return request.query_params.get("q", ""), set(request.query_params.getlist("hide"))


def done(request, session, writeup):
    query, hidden = board_state(request)
    location = f"{board_url(query, hidden, writeup.aircraft.tail_number)}#writeup-{writeup.id}"
    # Commit here rather than when get_session exits: FastAPI has already sent the response
    # by then, so a failed commit would go unreported.
    session.commit()
    return RedirectResponse(location, status_code=303)


def render_board(request, session, now, tail="", failure=None):
    query, hidden = board_state(request)
    aircraft = None
    if tail:
        aircraft = session.scalar(select(Aircraft).where(Aircraft.tail_number == tail))
        if aircraft is None:
            raise HTTPException(404, "Aircraft not found")
    today = service.today(now)
    context = {
        "board": service.board(session, today, query),
        "query": query,
        "hidden": hidden,
        "link": board_linker(query, hidden, tail),
        "form_query": board_url(query, hidden).removeprefix("/"),
        "aircraft": aircraft,
        "now": now,
        "today": today,
        "failure": failure,
    }
    if aircraft:
        context["status"] = service.AircraftStatus(aircraft, service.open_writeups(aircraft))
        context["timeline"] = service.timeline(aircraft)
    return templates.TemplateResponse(request, "board.html", context, status_code=400 if failure else 200)


async def render_failure(request, message, stale=False):
    """Re-renders the aircraft the failed form belonged to, with the message and what was typed."""
    params = request.path_params
    with Session(request.app.state.engine) as session:
        if "writeup_id" in params:
            writeup = session.get(Writeup, int(params["writeup_id"]))
            tail = writeup.aircraft.tail_number
            if stale:
                # The form that was submitted isn't on the card any more, so the panel carries the message.
                form_id = "panel"
                message = f"Write-up #{writeup.id} has changed since this page loaded. {message}"
            else:
                form_id = f"{writeup.id}-{request.url.path.rsplit('/', 1)[1]}"
        else:
            aircraft = session.get(Aircraft, int(params["aircraft_id"]))
            if aircraft is None:
                return PlainTextResponse("Aircraft not found", status_code=404)
            tail = aircraft.tail_number
            form_id = "file"
        failure = Failure(form_id, message, dict(await request.form()))
        return render_board(request, session, get_now(request), tail=tail, failure=failure)


def create_app(engine, clock=local_now):
    app = FastAPI()
    app.state.engine = engine
    app.state.clock = clock
    app.mount("/static", StaticFiles(directory=HERE / "static"), name="static")

    @app.exception_handler(RuleViolation)
    async def rule_violation(request, exc):
        return await render_failure(request, str(exc), stale=isinstance(exc, WrongStatus))

    @app.exception_handler(StaleDataError)
    async def changed_meanwhile(request, exc):
        return await render_failure(request, "Nothing was saved.", stale=True)

    @app.exception_handler(RequestValidationError)
    async def invalid_form(request, exc):
        if any(error["loc"][0] == "path" for error in exc.errors()):
            return PlainTextResponse("Not found", status_code=404)
        message = " ".join(
            f"{FIELD_LABELS[error['loc'][-1]]} is {'required' if error['type'] == 'missing' else 'invalid'}."
            for error in exc.errors()
        )
        return await render_failure(request, message)

    @app.get("/")
    def fleet(request: Request, session: DbSession, now: Now, aircraft: str = ""):
        return render_board(request, session, now, aircraft)

    # Text fields default to "" because FastAPI treats an empty form field as missing
    # and Annotated[..., Form()] can't carry a default; require_text in the service then
    # rejects blank and missing alike with a readable message.

    @app.post("/aircraft/{aircraft_id}/writeups")
    def file_writeup(
        request: Request, aircraft_id: int, session: DbSession, now: Now, severity: Annotated[Severity, Form()],
        reported_by: Text = "", description: Text = "", scheduled_date: Annotated[date | None, Form()] = None,
    ):
        if session.get(Aircraft, aircraft_id) is None:
            raise HTTPException(404, "Aircraft not found")
        writeup = service.file_writeup(session, aircraft_id, reported_by, description, severity, now, scheduled_date)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/schedule")
    def schedule(
        request: Request, writeup: LoadedWriteup, session: DbSession, now: Now,
        scheduled_date: Annotated[date, Form()], actor: Text = "",
    ):
        service.schedule(session, writeup, actor, scheduled_date, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/unschedule")
    def unschedule(request: Request, writeup: LoadedWriteup, session: DbSession, now: Now, actor: Text = ""):
        service.unschedule(session, writeup, actor, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/start")
    def start(request: Request, writeup: LoadedWriteup, session: DbSession, now: Now, actor: Text = ""):
        service.start(session, writeup, actor, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/resolve")
    def resolve(request: Request, writeup: LoadedWriteup, session: DbSession, now: Now, actor: Text = "", note: Text = ""):
        service.resolve(session, writeup, actor, note, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/cancel")
    def cancel(request: Request, writeup: LoadedWriteup, session: DbSession, now: Now, actor: Text = "", note: Text = ""):
        service.cancel(session, writeup, actor, note, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/severity")
    def change_severity(
        request: Request, writeup: LoadedWriteup, session: DbSession, now: Now,
        severity: Annotated[Severity, Form()], actor: Text = "", note: Text = "",
    ):
        service.change_severity(session, writeup, actor, severity, note, now)
        return done(request, session, writeup)

    @app.post("/writeups/{writeup_id}/description")
    def edit_description(request: Request, writeup: LoadedWriteup, session: DbSession, now: Now, actor: Text = "", description: Text = ""):
        service.edit_description(session, writeup, actor, description, now)
        return done(request, session, writeup)

    return app
from datetime import timedelta

from sqlalchemy import select

from app import service
from app.models import Aircraft
from app.rules import Severity

PILOT = "Capt. Dana Ruiz"
FIRST_OFFICER = "F/O Marcus Hale"
MECHANIC = "Sam Okafor"
LEAD_MECHANIC = "Lee Park"
CONTROLLER = "Jordan Bell"


def seed_if_empty(session, now):
    if session.scalar(select(Aircraft.id).limit(1)) is None:
        seed(session, now)


def seed(session, now):
    """Builds the demo fleet through the same actions the app uses, with backdated clocks,
    so every seeded write-up and audit entry is one the app could have produced."""

    def ago(days, hours=0):
        return now - timedelta(days=days, hours=hours)

    def day(offset):
        return service.today(now) + timedelta(days=offset)

    planes = {}
    for number in range(401, 431):
        plane = Aircraft(tail_number=f"N{number}TG")
        session.add(plane)
        planes[number] = plane
    session.flush()

    def file(number, severity, description, when, reporter=PILOT):
        return service.file_writeup(session, planes[number].id, reporter, description, severity, when)

    # N401: grounded by a fresh High nobody has scheduled yet.
    file(401, Severity.high, "Cracked outer pane on the left windshield", ago(0, 2))

    # N402: grounded by a High scheduled for tomorrow; an open Low alongside.
    w = file(402, Severity.high, "Hydraulic system B pressure fluctuating in cruise", ago(1))
    service.schedule(session, w, CONTROLLER, day(1), ago(1, -1))
    file(402, Severity.low, "Reading light at seat 14C flickers", ago(3), FIRST_OFFICER)

    # N403: grounded by an overdue High repair in progress that was already rescheduled once.
    w = file(403, Severity.high, "Engine 2 oil pressure warning light comes on intermittently", ago(6))
    service.schedule(session, w, CONTROLLER, day(-4), ago(6, -1))
    service.start(session, w, MECHANIC, ago(4))
    service.schedule(session, w, CONTROLLER, day(-1), ago(3))

    # N404: grounded by two Highs; resolving one isn't enough.
    w = file(404, Severity.high, "Left main gear tire worn to the cords", ago(2))
    service.schedule(session, w, CONTROLLER, day(0), ago(2, -1))
    service.start(session, w, MECHANIC, ago(0, 3))
    file(404, Severity.high, "Smoke detector in the aft lavatory fails self-test", ago(0, 5), FIRST_OFFICER)

    # N405: cleared once its High was fixed.
    w = file(405, Severity.high, "Pitot heat inoperative on the captain's side", ago(5))
    service.schedule(session, w, CONTROLLER, day(-3), ago(5, -1))
    service.start(session, w, LEAD_MECHANIC, ago(3, 1))
    service.resolve(session, w, LEAD_MECHANIC, "Replaced the pitot heater element; tested OK on the ground.", ago(3))

    # N406: cleared after a High was downgraded on inspection.
    w = file(406, Severity.high, "Dent on the leading edge of the right wing", ago(4))
    service.change_severity(
        session, w, LEAD_MECHANIC, Severity.medium,
        "Measured at 2 mm, within structural repair manual limits.", ago(3, 20),
    )
    service.schedule(session, w, CONTROLLER, day(10), ago(3, 18))

    # N407: cleared after a High turned out to be no fault.
    w = file(407, Severity.high, "Fuel quantity indication jumps between readings", ago(3))
    service.schedule(session, w, CONTROLLER, day(2), ago(3, -1))
    service.cancel(
        session, w, LEAD_MECHANIC,
        "No fault found: ran a full gauge test with no discrepancies.", ago(1),
    )

    # N408: cleared despite an overdue Medium; only Highs ground.
    w = file(408, Severity.medium, "Cabin temperature runs hot in the forward zone", ago(9), FIRST_OFFICER)
    service.schedule(session, w, CONTROLLER, day(-2), ago(9, -1))

    # N409: cleared with an unscheduled Low and a duplicate that was canceled before scheduling.
    file(409, Severity.low, "Galley cart latch sticks", ago(2), MECHANIC)
    w = file(409, Severity.low, "Galley cart latch hard to close", ago(1), FIRST_OFFICER)
    service.cancel(session, w, CONTROLLER, "Duplicate of the earlier galley cart write-up.", ago(0, 20))

    # N410: cleared; a Medium that lost its slot and had its description clarified.
    w = file(410, Severity.medium, "Cargo door seal worn", ago(4), MECHANIC)
    service.schedule(session, w, CONTROLLER, day(1), ago(4, -1))
    service.edit_description(session, w, MECHANIC, "Forward cargo door seal worn along the bottom edge", ago(3))
    service.unschedule(session, w, CONTROLLER, ago(1))

    # N411: cleared with a Medium repair in progress and on time.
    w = file(411, Severity.medium, "Autopilot disconnect warning tone is faint", ago(2))
    service.schedule(session, w, CONTROLLER, day(3), ago(2, -1))
    service.start(session, w, MECHANIC, ago(0, 4))

    # N412: cleared; a Low fixed earlier, for history.
    w = file(412, Severity.low, "Tray table at seat 22A won't latch", ago(8), FIRST_OFFICER)
    service.schedule(session, w, CONTROLLER, day(-6), ago(8, -1))
    service.start(session, w, MECHANIC, ago(6, 2))
    service.resolve(session, w, MECHANIC, "Replaced the latch assembly.", ago(6))

    session.commit()

