{{- "yes" if failure and failure.form_id in form_ids else "" -}}
{%- endmacro -%}

{%- macro kept(form_id, field, default="") -%}
{{ failure.values.get(field, default) if failure and failure.form_id == form_id else default }}
{%- endmacro -%}

{%- macro error_for(form_ids) -%}
{% if failed(form_ids) %}<p class="error" role="alert">{{ failure.message }}</p>{% endif %}
{%- endmacro -%}

{%- macro name_field(form_id, field="actor") -%}
<label class="field">
  <span>Your name</span>
  <input name="{{ field }}" required autocomplete="name" value="{{ kept(form_id, field) }}">
</label>
{%- endmacro -%}

{%- macro note_field(form_id, label) -%}
<label class="field">
  <span>{{ label }}</span>
  <textarea name="note" rows="2" required>{{ kept(form_id, 'note') }}</textarea>
</label>
{%- endmacro -%}

{%- macro date_input(form_id, current, required=true) -%}
<input type="date" name="scheduled_date" min="{{ today.isoformat() }}"{% if required %} required{% endif %}
  value="{{ kept(form_id, 'scheduled_date', current.isoformat() if current else '') }}">
{%- endmacro -%}

{#- One editable part of a card: the summary is the thing itself, and opening it shows its form. -#}
{%- macro edit(writeup, name, kind, form_ids=none) -%}
{% set form_ids = form_ids or [writeup.id ~ "-" ~ name] %}
<details class="edit edit-{{ kind }}" name="writeup-{{ writeup.id }}"{% if failed(form_ids) %} open{% endif %}>
  {{ caller() }}
</details>
{%- endmacro -%}

{%- macro event_text(entry) -%}
{% set event = entry.event %}
{% if event is none %}Filed as {{ filed_severity(entry.writeup) | capitalize }}
{% elif event.kind == "scheduled" %}Scheduled for {{ event.to_value | day }}
{% elif event.kind == "rescheduled" %}Rescheduled from {{ event.from_value | day }} to {{ event.to_value | day }}
{% elif event.kind == "unscheduled" %}Unscheduled; was {{ event.from_value | day }}
{% elif event.kind == "started" %}Work started
{% elif event.kind == "resolved" %}Resolved
{% elif event.kind == "canceled" %}Canceled
{% elif event.kind == "severity_changed" %}Severity changed from {{ event.from_value | capitalize }} to {{ event.to_value | capitalize }}
{% elif event.kind == "description_edited" %}Description changed; was “{{ event.from_value }}”
{% endif %}
{%- endmacro -%}

