          {% call edit(writeup, "severity", "severity") %}
          <summary class="severity severity-{{ writeup.severity }}" aria-label="Severity {{ writeup.severity }}, change it">{{ writeup.severity }}</summary>
          <form class="popover" method="post" action="/writeups/{{ id }}/severity{{ form_query }}">
            {{ error_for([id ~ "-severity"]) }}
            <label class="field">
              <span>Change severity to</span>
              <select name="severity" required>
                <option value="">Choose</option>
                {% for severity in Severity if severity != writeup.severity %}
                <option value="{{ severity }}"{% if kept(id ~ '-severity', 'severity') == severity %} selected{% endif %}>{{ severity | capitalize }}</option>
                {% endfor %}
              </select>
            </label>
            {{ note_field(id ~ "-severity", "Reason") }}
            {{ name_field(id ~ "-severity") }}
            <button class="button">Change severity</button>
          </form>
          {% endcall %}

          <span class="state">{{ writeup.status | replace("_", " ") | capitalize }}</span>

          <div class="corner">
            {% if is_overdue(writeup, today) %}<span class="flag">Overdue</span>{% endif %}
            {% if writeup.scheduled_date %}
            {% call edit(writeup, "schedule", "date", [id ~ "-schedule", id ~ "-unschedule"]) %}
            <summary class="date" aria-label="Scheduled {{ writeup.scheduled_date | day }}, reschedule">{{ writeup.scheduled_date | day }}</summary>
            <form class="popover popover-end" method="post" action="/writeups/{{ id }}/schedule{{ form_query }}">
              {{ error_for([id ~ "-schedule", id ~ "-unschedule"]) }}
              <label class="field"><span>Reschedule to</span>{{ date_input(id ~ "-schedule", writeup.scheduled_date) }}</label>
              {{ name_field(id ~ "-schedule") }}
              <div class="form-actions">
                <button class="button">Reschedule</button>
                {% if writeup.status == "scheduled" %}
                <button class="link-button" formaction="/writeups/{{ id }}/unschedule{{ form_query }}" formnovalidate>Remove date</button>
                {% endif %}
              </div>
            </form>
            {% endcall %}
            {% else %}
            <span class="flag">Needs scheduling</span>
            {% endif %}
          </div>
        </div>

        {% call edit(writeup, "description", "description") %}
        <summary>{{ writeup.description }}</summary>
        <form method="post" action="/writeups/{{ id }}/description{{ form_query }}">
          {{ error_for([id ~ "-description"]) }}
          <label class="field">
            <span>Description</span>
            <textarea name="description" rows="3" required>{{ kept(id ~ '-description', 'description', writeup.description) }}</textarea>
          </label>
          {{ name_field(id ~ "-description") }}
          <button class="button">Save description</button>
        </form>
        {% endcall %}

        <p class="meta">#{{ id }} · {{ writeup.reported_by }} · {{ writeup.reported_at | local_time }}</p>

        <div class="card-actions">
          {% if writeup.status == "unscheduled" %}
          {% call edit(writeup, "schedule", "step") %}
          <summary class="button">Schedule</summary>
          <form method="post" action="/writeups/{{ id }}/schedule{{ form_query }}">
            {{ error_for([id ~ "-schedule"]) }}
            <label class="field"><span>Scheduled date</span>{{ date_input(id ~ "-schedule", none) }}</label>
            {{ name_field(id ~ "-schedule") }}
            <button class="button">Schedule</button>
          </form>
          {% endcall %}
          {% elif writeup.status == "scheduled" %}
          {% call edit(writeup, "start", "step") %}
          <summary class="button">Start work</summary>
          <form method="post" action="/writeups/{{ id }}/start{{ form_query }}">
            {{ error_for([id ~ "-start"]) }}
            {{ name_field(id ~ "-start") }}
            <button class="button">Start work</button>
          </form>
          {% endcall %}
          {% else %}
          {% call edit(writeup, "resolve", "step") %}
          <summary class="button">Resolve</summary>
          <form method="post" action="/writeups/{{ id }}/resolve{{ form_query }}">
            {{ error_for([id ~ "-resolve"]) }}
            {{ note_field(id ~ "-resolve", "What was done") }}
            {{ name_field(id ~ "-resolve") }}
            <button class="button">Resolve</button>
          </form>
          {% endcall %}
          {% endif %}

          {% call edit(writeup, "cancel", "cancel") %}
          <summary class="cancel-link">Cancel write-up</summary>
          <form class="popover popover-end" method="post" action="/writeups/{{ id }}/cancel{{ form_query }}">
            {{ error_for([id ~ "-cancel"]) }}
            {{ note_field(id ~ "-cancel", "Why cancel it") }}
            {{ name_field(id ~ "-cancel") }}
            <button class="button">Cancel write-up</button>
          </form>
          {% endcall %}
        </div>
      </article>
      {% else %}
      <p class="empty">No open write-ups.</p>
      {% endfor %}
    </section>

    <section class="history" aria-labelledby="history-title">
      <h3 id="history-title">History</h3>
      <ol class="timeline">
        {% for entry in timeline %}
        <li>
          <p class="when"><time>{{ entry.at | local_time }}</time> · {{ entry.actor }}</p>
          <p>{{ event_text(entry) }}</p>
          {% if entry.event and entry.event.note %}<p class="note">{{ entry.event.note }}</p>{% endif %}
          <p class="ref">#{{ entry.writeup.id }} {{ entry.writeup.description }}</p>
        </li>
        {% else %}
        <li class="empty">Nothing has been filed against this aircraft.</li>
        {% endfor %}
      </ol>
    </section>
  </aside>
  {% endif %}

</div>
<script src="/static/scroll.js"></script>
</body>
</html>

