summary { cursor: pointer; list-style: none; }
summary::-webkit-details-marker { display: none; }

/* Labels and data in mono, as on tagup.ai. */
.fleet thead th, .group-head, .status, .flag, .severity, .state, .date,
.summary, .search label, .field > span, .field legend, .panel-close, .button,
.history h3, .open-writeups h3, .when {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
textarea { resize: vertical; width: 100%; }

.fleet { width: 100%; border-collapse: collapse; }

.fleet th, .fleet td {
  padding: 0.6rem 0.75rem;
  text-align: left;
  vertical-align: baseline;
  border-bottom: 1px solid var(--border);
}

.fleet thead th { color: var(--muted); padding-block: 0.5rem; }

.fleet .group-head > * { padding-top: 1.75rem; border-bottom-color: currentColor; }
.group-head span { margin-left: 0.5rem; }
.group-grounded .group-head { color: var(--grounded); }
.group-cleared .group-head { color: var(--cleared); }
.group-head .toggle { text-align: right; }
.toggle a { color: var(--muted); text-decoration: none; }
.toggle a:hover { color: var(--fg); }

.group-grounded .aircraft { background: var(--grounded-tint); }

.aircraft { position: relative; }
.aircraft:hover { background: var(--raised); }
.aircraft[aria-current="true"] { background: var(--raised); box-shadow: inset 0 0 0 1px var(--muted); }

.tail { width: 7rem; white-space: nowrap; }
.tail a {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
}
/* The whole row opens the aircraft. */
.tail a::after { content: ""; position: absolute; inset: 0; }
.tail a:focus-visible { outline: none; }
.tail a:focus-visible::after { outline: 2px solid var(--fg); outline-offset: -2px; }

/* Chips: the box is trimmed to the capitals so the padding is the visible inset on every side.
   The right side gives back the letter-spacing the last letter carries. */
.status, .state, .flag {
  display: inline-block;
  font-size: 11px;
  line-height: 1;
  text-box: trim-both cap alphabetic;
  padding: 0.5em calc(0.75em - 0.06em) 0.5em 0.75em;
  border: 1px solid transparent;
  white-space: nowrap;
}

/* Clearance is a filled chip so it never reads like a High severity label, which is bare text. */
.status {
  border-color: color-mix(in srgb, currentColor 45%, transparent);
  background: color-mix(in srgb, currentColor 14%, transparent);
}
.status-grounded { color: var(--grounded); }
.status-cleared { color: var(--cleared); }

/* A fixed severity column, so a wrapped description never reads as a second write-up. */
.row-writeups { list-style: none; padding: 0; display: grid; gap: 0.3rem; }
.row-writeups li { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr); align-items: baseline; gap: 0.5rem; max-width: 56ch; }
.no-writeups { color: var(--muted); font-size: 14px; }

.severity { font-size: 11px; color: var(--muted); }
.severity-high { color: var(--grounded); }
.severity-medium { color: var(--fg); }

